EXTRACT ( YEAR FROM ${timeFlag} ) = EXTRACT ( YEAR FROM NOW()-interval '1 years' )


    AND o.dept_id IN

        #{deptId}




    AND o.source_platform IN

        #{platform}




    AND o.site IN

        #{site}




    AND o.shop_no IN

        #{shopNo}




    AND i.platform_sku IN

        #{sku}




    AND i.category_id IN

        #{category}




    AND i.brand_id IN

        #{brand}




    AND o.charge_id IN

        #{userId}




    #{params.param}


GROUP BY
EXTRACT ( MONTH FROM ${timeFlag} )

SELECT round( SUM ( o.order_fee * o.currency_rate ) / 10000, 4 ) AS sales,
COUNT ( DISTINCT ( i.order_id ) ) AS orderCount,SUM ( i.quantity ) AS salesQuantity
FROM dmp_order_item i
LEFT JOIN dmp_order_info o ON i.order_id = o.id




            o.platform_create_time >= #{params.startTime}


            AND o.platform_create_time <= #{params.endTime}





            AND o.delivery_time >= #{params.startTime}


            AND o.delivery_time <= #{params.endTime}




        AND o.dept_id IN

            #{deptId}




        AND o.source_platform IN

            #{platform}




        AND o.site IN

            #{site}




        AND o.shop_no IN

            #{shopNo}




        AND i.platform_sku IN

            #{sku}




        AND i.category_id IN

            #{category}




        AND i.brand_id IN

            #{brand}




        AND o.charge_id IN

            #{userId}




